/// <summary>
/// PaffH 20.07.23
/// </summary>
/// <param name = "_args">Args</param>
/// <returns>SysOperationController</returns>
[SuppressBPWarning('BPParameterNotUsed','Parameter "_args"')]
public static SysOperationController construct(Args _args)
{
    SysOperationController controller = new NDXPALabelAdministratedController(
        classStr(NDXPALabelAdministratedProcessing),
        methodStr(NDXPALabelAdministratedProcessing, Run));
    return controller;
}

/// <summary>
/// PaffH 20.07.23
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    NDXPALabelAdministratedController::construct(_args).startOperation();
}

